class Solution {
public:
    int minimumCost(string sentence, int k) {
        vector<int> lengths;
        string word;
        stringstream ss(sentence);
        while (ss >> word) lengths.push_back(word.size());
        int n = lengths.size();
        const int INF = 1000000000;
        vector<int> dp(n + 1, INF);
        dp[n] = 0;
        for (int i = n - 1; i >= 0; --i) {
            int width = 0;
            for (int j = i; j < n; ++j) {
                width += lengths[j] + (j > i ? 1 : 0);
                if (width > k) break;
                int cost = (j == n - 1 ? 0 : (k - width) * (k - width));
                dp[i] = min(dp[i], cost + dp[j + 1]);
            }
        }
        return dp[0];
    }
};
